package com.zhuqiyun;

import com.zhuqiyun.platform.*;
import com.zhuqiyun.procurement.ProcurementService;
import com.zhuqiyun.inventory.*;
import com.zhuqiyun.finance.FinanceService;
import com.zhuqiyun.project.ProjectService;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import static com.zhuqiyun.domain.Rules.*;
import static org.junit.jupiter.api.Assertions.*;

/** No enclosing test transaction: rollback assertions observe real service transaction boundaries. */
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:adjustments;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1;NON_KEYWORDS=VALUE","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","spring.flyway.enabled=false","spring.sql.init.mode=always","spring.sql.init.schema-locations=classpath:db/migration/V1__schema.sql,classpath:db/migration/V4__payment_application_approval.sql,classpath:db/migration/V5__procurement_adjustments.sql","app.seed=true"})
class ProcurementAdjustmentTest {
 @Autowired Db db; @Autowired ProcurementService procurement; @Autowired InventoryService inventory; @Autowired AdjustmentService adjustments; @Autowired FinanceService finance; @Autowired ProjectService projects;
 long project,material,warehouse,supplier;String run;
 @BeforeEach void setup(){as("admin");project=num(db.one("SELECT id FROM projects WHERE code='PRJ-2026-001'"),"id");material=num(db.one("SELECT id FROM materials ORDER BY id LIMIT 1"),"id");supplier=num(db.one("SELECT id FROM suppliers WHERE status='ACTIVE' ORDER BY id LIMIT 1"),"id");run=code("TEST");warehouse=db.insert("warehouses",row("code",run,"name","纠错隔离仓","location",run));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 void as(String name){long id=num(db.one("SELECT id FROM users WHERE username=?",name),"id");SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(id,null,List.of()));}
 long num(Map<String,Object> r,String key){return ((Number)r.get(key)).longValue();}long id(Map<String,Object> r){return num(r,"id");}
 void amount(String expected,Object actual){assertEquals(0,new BigDecimal(expected).compareTo(dec(actual)));}
 void status(int code,org.junit.jupiter.api.function.Executable action){assertEquals(code,assertThrows(ResponseStatusException.class,action).getStatusCode().value());}
 Map<String,Object> order(String price){as("manager");Map<String,Object> request=procurement.save(null,row("project_id",project,"required_date",LocalDate.now().plusDays(10),"items",List.of(row("material_id",material,"quantity","10.000","unit_price",price))));procurement.submit(id(request));as("boss");procurement.approve(id(request),row("decision","APPROVED","comment",run));as("buyer");Map<String,Object> quote=procurement.quote(id(request),row("supplier_id",supplier,"delivery_days",3,"valid_until",LocalDate.now().plusDays(10),"items",List.of(row("request_item_id",id(((List<Map<String,Object>>)request.get("items")).get(0)),"unit_price",price))));return procurement.award(id(request),row("quote_id",id(quote),"reason",run));}
 Map<String,Object> receipt(Map<String,Object> o,String quantity){as("warehouse");return inventory.receive(id(o),row("warehouse_id",warehouse,"reference",code("GR"),"items",List.of(row("order_item_id",id(((List<Map<String,Object>>)o.get("items")).get(0)),"quantity",quantity))));}
 Map<String,Object> issue(String quantity){as("warehouse");return inventory.issue(row("project_id",project,"warehouse_id",warehouse,"reference",code("MI"),"items",List.of(row("material_id",material,"quantity",quantity))));}
 Map<String,Object> stock(){return db.one("SELECT * FROM inventory WHERE warehouse_id=? AND material_id=?",warehouse,material);}
 Map<String,Object> payable(Map<String,Object> order){return db.one("SELECT * FROM payables WHERE order_id=?",id(order));}
 Map<String,Object> returnPurchase(Map<String,Object> receipt,String quantity){as("warehouse");long source=num(db.one("SELECT id FROM receipt_items WHERE receipt_id=?",id(receipt)),"id");return adjustments.returnPurchase(id(receipt),row("reference",code("SR"),"reason",run,"items",List.of(row("source_id",source,"quantity",quantity))));}
 Map<String,Object> returnIssue(Map<String,Object> issue,String quantity){as("warehouse");long source=num(db.one("SELECT id FROM stock_movements WHERE issue_id=? AND kind='ISSUE'",id(issue)),"id");return adjustments.returnIssue(id(issue),row("reference",code("IR"),"reason",run,"items",List.of(row("source_id",source,"quantity",quantity))));}
 @Test void closeKeepsOriginalsAndReorderRequiresFreshApproval(){Map<String,Object> o=order("10");receipt(o,"6");as("buyer");Map<String,Object> closed=procurement.close(id(o),row("reason","供应商终止剩余供货"));assertEquals("CLOSED",closed.get("status"));amount("100",closed.get("total_amount"));amount("40",closed.get("closed_amount"));amount("60",closed.get("effective_amount"));amount("60",payable(o).get("amount"));status(409,()->procurement.close(id(o),row("reason",run)));status(409,()->receipt(o,"1"));as("manager");Map<String,Object> draft=procurement.reorder(id(o),row("required_date",LocalDate.now().plusDays(12),"note",run));assertEquals("DRAFT",draft.get("status"));assertEquals(id(o),num(draft,"source_order_id"));amount("40",draft.get("total_amount"));amount("4",((List<Map<String,Object>>)draft.get("items")).get(0).get("quantity"));status(409,()->procurement.reorder(id(o),row("required_date",LocalDate.now().plusDays(12))));}
 @Test void cancelledOrderCanCreateOneLinkedReplacement(){Map<String,Object> o=order("10");procurement.cancel(id(o),row("reason",run));as("manager");Map<String,Object> draft=procurement.reorder(id(o),row("required_date",LocalDate.now().plusDays(7)));amount("100",draft.get("total_amount"));assertEquals("DRAFT",draft.get("status"));as("buyer");status(403,()->procurement.reorder(id(o),row("required_date",LocalDate.now().plusDays(7))));}
 @Test void projectReturnRestoresOriginalCostAndDoesNotTouchCash(){Map<String,Object> o=order("10");receipt(o,"6");as("admin");BigDecimal before=dec(projects.metrics(project).get("material_cost"));Map<String,Object> issue=issue("3");Map<String,Object> back=returnIssue(issue,"2");amount("20",back.get("amount"));amount("5",stock().get("quantity"));amount("50",stock().get("stock_value"));amount("60",payable(o).get("amount"));amount("0",payable(o).get("paid_amount"));as("admin");amount(before.add(new BigDecimal("10")).toString(),projects.metrics(project).get("material_cost"));status(409,()->returnIssue(issue,"2"));}
 @Test void projectReturnUsesHistoricIssueCostAfterAverageChanges(){Map<String,Object> first=order("10");receipt(first,"10");Map<String,Object> issue=issue("4");Map<String,Object> second=order("20");receipt(second,"10");amount("260",stock().get("stock_value"));Map<String,Object> back=returnIssue(issue,"2");amount("20",back.get("amount"));amount("18",stock().get("quantity"));amount("280",stock().get("stock_value"));}
 @Test void fractionalReturnsAbsorbFinalCent(){Map<String,Object> o=order("0.0033");receipt(o,"3");Map<String,Object> issued=issue("3");amount("0.01",issued.get("amount"));BigDecimal total=BigDecimal.ZERO;for(int i=0;i<3;i++)total=total.add(dec(returnIssue(issued,"1").get("amount")));amount("0.01",total);amount("3",stock().get("quantity"));amount("0.01",stock().get("stock_value"));status(409,()->returnIssue(issued,"0.001"));}
 @Test void unpaidPurchaseReturnReducesInventoryAndPayable(){Map<String,Object> o=order("10");Map<String,Object> receipt=receipt(o,"6");Map<String,Object> back=returnPurchase(receipt,"2");amount("20",back.get("amount"));amount("20",back.get("stock_amount"));amount("0",back.get("variance_amount"));amount("4",stock().get("quantity"));amount("40",payable(o).get("amount"));as("buyer");amount("80",procurement.orderDetail(id(o)).get("effective_amount"));amount("60",db.one("SELECT amount FROM receipts WHERE id=?",id(receipt)).get("amount"));}
 @Test void consumedStockCannotBeReturnedToSupplier(){Map<String,Object> o=order("10");Map<String,Object> receipt=receipt(o,"6");issue("6");status(409,()->returnPurchase(receipt,"1"));amount("0",stock().get("quantity"));amount("60",payable(o).get("amount"));assertTrue(db.list("SELECT id FROM purchase_returns WHERE receipt_id=?",id(receipt)).isEmpty());}
 @Test void paidReturnCreatesReceivableAndRefundIsPartialUniqueAndBounded(){Map<String,Object> o=order("10");Map<String,Object> receipt=receipt(o,"10");as("admin");finance.payment(row("payable_id",id(payable(o)),"amount","100","reference",run));returnPurchase(receipt,"4");amount("60",payable(o).get("amount"));amount("100",payable(o).get("paid_amount"));as("finance");Map<String,Object> body=row("payable_id",id(payable(o)),"amount","15","reference",run+"-REF");adjustments.refund(body);status(409,()->adjustments.refund(body));status(409,()->adjustments.refund(row("payable_id",id(payable(o)),"amount","25.01","reference",run+"-OVER")));adjustments.refund(row("payable_id",id(payable(o)),"amount","25","reference",run+"-LAST"));amount("60",payable(o).get("paid_amount"));amount("100",db.one("SELECT amount FROM payments WHERE reference=?",run).get("amount"));status(409,()->adjustments.refund(row("payable_id",id(payable(o)),"amount","0.01","reference",run+"-EXTRA")));}
 @Test void reservationConflictRollsBackStockAndReturnRecords(){Map<String,Object> o=order("10");Map<String,Object> receipt=receipt(o,"6");as("finance");Map<String,Object> application=finance.apply(row("payable_id",id(payable(o)),"amount","40"));status(409,()->returnPurchase(receipt,"3"));amount("6",stock().get("quantity"));amount("60",stock().get("stock_value"));amount("60",payable(o).get("amount"));assertTrue(db.list("SELECT id FROM purchase_returns WHERE receipt_id=?",id(receipt)).isEmpty());as("finance");finance.cancelApplication(id(application),row("reason",run));returnPurchase(receipt,"3");amount("30",payable(o).get("amount"));}
 @Test void movingAverageVarianceIsSignedAndTraceable(){Map<String,Object> a=order("10"),b=order("20");Map<String,Object> ra=receipt(a,"10"),rb=receipt(b,"10");as("admin");BigDecimal before=dec(projects.metrics(project).get("other_cost"));Map<String,Object> first=returnPurchase(ra,"2");amount("20",first.get("amount"));amount("30",first.get("stock_amount"));amount("10",first.get("variance_amount"));amount("10",db.one("SELECT amount FROM costs WHERE id=?",first.get("cost_id")).get("amount"));as("admin");amount(before.add(new BigDecimal("10")).toString(),projects.metrics(project).get("other_cost"));Map<String,Object> second=returnPurchase(rb,"2");amount("-10",second.get("variance_amount"));amount("16",stock().get("quantity"));amount("240",stock().get("stock_value"));as("admin");amount(before.toString(),projects.metrics(project).get("other_cost"));}
 @Test void fullPurchaseReturnsLeaveZeroInventoryAndNoArtificialVariance(){Map<String,Object> a=order("10"),b=order("20");Map<String,Object> ra=receipt(a,"10"),rb=receipt(b,"10");BigDecimal variance=dec(returnPurchase(ra,"10").get("variance_amount")).add(dec(returnPurchase(rb,"10").get("variance_amount")));amount("0",variance);amount("0",stock().get("quantity"));amount("0",stock().get("stock_value"));amount("0",payable(a).get("amount"));amount("0",payable(b).get("amount"));}
 @Test void invalidSecondLineRollsBackTheWholeReturn(){Map<String,Object> o=order("10");Map<String,Object> receipt=receipt(o,"6");long source=num(db.one("SELECT id FROM receipt_items WHERE receipt_id=?",id(receipt)),"id");as("warehouse");status(404,()->adjustments.returnPurchase(id(receipt),row("reference",run,"reason",run,"items",List.of(row("source_id",source,"quantity","1"),row("source_id",Long.MAX_VALUE,"quantity","1")))));amount("6",stock().get("quantity"));amount("60",payable(o).get("amount"));assertTrue(db.list("SELECT id FROM purchase_returns WHERE reference=?",run).isEmpty());}
 @Test void returnSourceOwnershipAndDuplicateReferenceAreEnforced(){Map<String,Object> o=order("10");Map<String,Object> r=receipt(o,"6");Map<String,Object> other=receipt(order("10"),"2");long source=num(db.one("SELECT id FROM receipt_items WHERE receipt_id=?",id(other)),"id");as("warehouse");status(404,()->adjustments.returnPurchase(id(r),row("reference",run,"reason",run,"items",List.of(row("source_id",source,"quantity","1")))));long valid=num(db.one("SELECT id FROM receipt_items WHERE receipt_id=?",id(r)),"id");Map<String,Object> body=row("reference",run,"reason",run,"items",List.of(row("source_id",valid,"quantity","1")));adjustments.returnPurchase(id(r),body);status(409,()->adjustments.returnPurchase(id(r),body));}
 @Test void permissionsAndManagerObjectScopeRemainServerEnforced(){Map<String,Object> o=order("10");Map<String,Object> r=receipt(o,"6");as("buyer");status(403,()->adjustments.returnPurchase(id(r),row("reference",run,"reason",run,"items",List.of())));as("warehouse");status(403,()->adjustments.refund(row("payable_id",id(payable(o)),"amount","1","reference",run)));as("buyer");procurement.close(id(o),row("reason",run));Object original=db.one("SELECT manager_id FROM projects WHERE id=?",project).get("manager_id");try{db.jdbc().update("UPDATE projects SET manager_id=(SELECT id FROM users WHERE username='boss') WHERE id=?",project);as("manager");status(403,()->procurement.reorder(id(o),row("required_date",LocalDate.now().plusDays(10))));assertTrue(adjustments.issues().stream().noneMatch(i->num(i,"project_id")==project));}finally{db.jdbc().update("UPDATE projects SET manager_id=? WHERE id=?",original,project);}}
}
